import music21
from music21 import stream, note, chord, meter, tempo, instrument, dynamics, articulations, expressions, clef, metadata

score = stream.Score()
score.metadata = metadata.Metadata()
score.metadata.title = 'A Window Made of Echoes'
score.metadata.composer = 'OpenAI'

clarinet = stream.Part(id='Clarinet')
violin = stream.Part(id='Violin')
cello = stream.Part(id='Cello')
piano = stream.Part(id='Piano')
clarinet.insert(0, instrument.Clarinet())
violin.insert(0, instrument.Violin())
cello.insert(0, instrument.Violoncello())
piano.insert(0, instrument.Piano())
clarinet.insert(0, clef.TrebleClef())
violin.insert(0, clef.TrebleClef())
cello.insert(0, clef.BassClef())
piano.insert(0, clef.TrebleClef())
parts = [clarinet, violin, cello, piano]
for part in parts:
    part.insert(0, meter.TimeSignature('4/4'))
clarinet.insert(0, tempo.MetronomeMark(number=84, text='Quietly, with curiosity'))
score.atSoundingPitch = True

# Each harmony specifies a bass and an airy, three-note upper voicing.
H = {
    'dm': (38, [62, 65, 69]),
    'bf': (34, [62, 65, 70]),
    'f':  (41, [60, 65, 69]),
    'c':  (36, [60, 64, 67]),
    'gm': (43, [62, 67, 70]),
    'a':  (33, [61, 64, 69]),
    'em': (40, [62, 64, 67]),
    'd':  (38, [62, 66, 69]),
    'g':  (43, [62, 67, 71]),
    'open': (38, [62, 64, 69])
}
progressions = [
    ['dm', 'bf', 'f', 'c', 'gm', 'dm', 'a', 'dm'],
    ['f', 'c', 'bf', 'f', 'gm', 'bf', 'a', 'dm'],
    ['gm', 'dm', 'em', 'a', 'bf', 'gm', 'a', 'a'],
    ['dm', 'c', 'bf', 'f', 'gm', 'dm', 'a', 'dm'],
    ['d', 'g', 'd', 'a', 'bf', 'g', 'd', 'open']
]
levels = ['p', 'mp', 'mf', 'pp', 'p']
labels = ['I. A question', 'II. Reflected light', 'III. Many answers', 'IV. Remembering', 'V. An open window']


def add_note(measure, pitch, duration, soft=False):
    n = note.Note(pitch, quarterLength=duration)
    if soft:
        n.articulations.append(articulations.Tenuto())
    measure.append(n)
    return n

for section, progression in enumerate(progressions):
    for local, name in enumerate(progression):
        number = section * 8 + local + 1
        bass, upper = H[name]
        u, v, w = upper
        mc, mv, mb, mp = [stream.Measure(number=number) for _ in range(4)]
        if local == 0:
            for m in [mc, mv, mb, mp]:
                m.insert(0, dynamics.Dynamic(levels[section]))
            mc.insert(0, expressions.TextExpression(labels[section]))

        if number == 40:
            add_note(mc, 76, 4, True)
            add_note(mv, 69, 4, True)
            add_note(mb, 38, 4, True)
            closing = chord.Chord([50, 57, 62, 64, 69], quarterLength=4)
            closing.expressions.append(expressions.Fermata())
            mp.append(closing)
            for m in [mc, mv, mb]:
                m.notes[0].expressions.append(expressions.Fermata())
        else:
            # The same contour changes its pace and its harmonic vocabulary.
            if section == 0:
                melody = [(u + 12, 1), (v + 12, 0.5), (w + 12, 0.5), (v + 12, 1)]
                for pitch, dur in melody:
                    add_note(mc, pitch, dur, dur == 1)
                if local % 4 == 3:
                    mc.append(note.Rest(quarterLength=1))
                else:
                    add_note(mc, u + 12, 1)
            elif section == 1:
                for pitch, dur in [(v + 12, 1.5), (u + 12, 0.5), (w + 12, 1), (v + 12, 1)]:
                    add_note(mc, pitch, dur)
            elif section == 2:
                for pitch in [u + 12, v + 12, w + 12, v + 12, u + 12, w + 12]:
                    add_note(mc, pitch, 0.5)
                add_note(mc, v + 12, 1, True)
            elif section == 3:
                mc.append(note.Rest(quarterLength=0.5))
                for pitch, dur in [(u + 12, 1.5), (v + 12, 0.5), (w + 12, 0.5), (u + 12, 1)]:
                    add_note(mc, pitch, dur, dur >= 1)
            else:
                for pitch, dur in [(w + 12, 1.5), (v + 12, 0.5), (u + 12, 2)]:
                    add_note(mc, pitch, dur, dur >= 1)

            if section == 0:
                mv.append(note.Rest(quarterLength=2))
                add_note(mv, v + 12, 2, True)
            elif section == 1:
                for pitch, dur in [(u + 12, 1), (v + 12, 1), (w + 12, 2)]:
                    add_note(mv, pitch, dur, True)
            elif section == 2:
                mv.append(note.Rest(quarterLength=0.5))
                for pitch, dur in [(w + 12, 1), (v + 12, 0.5), (u + 12, 1), (v + 12, 1)]:
                    add_note(mv, pitch, dur)
            elif section == 3:
                add_note(mv, w, 3, True)
                mv.append(note.Rest(quarterLength=1))
            else:
                add_note(mv, v + 12, 2, True)
                add_note(mv, w, 2, True)

            add_note(mb, bass, 3, True)
            add_note(mb, bass + 7 if name != 'em' else bass + 6, 1, True)

            if section == 2:
                pattern = [u - 12, w, v, u, w, v, u, v]
                for pitch in pattern:
                    add_note(mp, pitch, 0.5)
            elif section == 3:
                mp.append(chord.Chord([u - 12, v, w], quarterLength=2))
                mp.append(note.Rest(quarterLength=1))
                add_note(mp, u, 1)
            else:
                for pitch in [u - 12, w, v, u]:
                    add_note(mp, pitch, 1)

        if number == 40:
            for m in [mc, mv, mb, mp]:
                m.rightBarline = 'final'
        for part, measure in zip(parts, [mc, mv, mb, mp]):
            part.append(measure)

for part in parts:
    score.insert(0, part)

import music21
from music21 import stream, note, chord, meter, tempo, clef, instrument, dynamics, expressions, articulations, spanner, layout, metadata, bar

score = stream.Score(id='ListeningLattice')
score.metadata = metadata.Metadata()
score.metadata.title = 'A Lattice That Listens'
score.metadata.composer = 'OpenAI'
score.atSoundingPitch = True

# Each harmony supplies a bass, a piano voicing, and a local modal vocabulary.
harmonies = {
    'D':  (38, [57, 60, 64, 65], 2,  [0, 2, 3, 5, 7, 9, 10]),
    'Bb': (46, [57, 60, 62, 65, 76], 10, [0, 2, 4, 6, 7, 9, 11]),
    'C':  (36, [55, 57, 62, 64], 0,  [0, 2, 4, 5, 7, 9, 10]),
    'Am': (45, [55, 59, 60, 62, 64], 9, [0, 2, 3, 5, 7, 8, 10]),
    'E':  (40, [55, 58, 62, 69], 4,  [0, 1, 3, 5, 6, 8, 10]),
    'G':  (43, [57, 59, 62, 65], 7,  [0, 2, 4, 5, 7, 9, 10]),
    'Eb': (39, [55, 58, 62, 65], 3,  [0, 2, 4, 6, 7, 9, 11]),
    'As': (45, [55, 59, 62, 64], 9,  [0, 2, 3, 5, 7, 9, 10]),
    'A7': (45, [55, 59, 61, 64], 9,  [0, 2, 4, 5, 7, 9, 10])
}
progression = [
    'D', 'D', 'Bb', 'Bb', 'C', 'Am', 'E', 'D',
    'D', 'G', 'C', 'Am', 'Bb', 'E', 'As', 'A7',
    'D', 'Eb', 'D', 'G', 'Bb', 'C', 'E', 'A7',
    'D', 'D', 'Bb', 'Bb', 'G', 'G', 'Am', 'Am',
    'Bb', 'C', 'D', 'D', 'E', 'As', 'D', 'D'
]
meters = []
for i in range(40):
    if i < 8 or 16 <= i < 24:
        meters.append('5/4' if i % 2 == 0 else '4/4')
    elif i < 16:
        meters.append('7/8')
    elif i < 32:
        meters.append('4/4')
    else:
        meters.append('5/4' if i < 36 else '4/4')
lengths = [meter.TimeSignature(ts).barDuration.quarterLength for ts in meters]

parts = {}
settings = [
    ('flute', 'Flute', 'Fl.', instrument.Flute(), clef.TrebleClef()),
    ('clarinet', 'Clarinet', 'Cl.', instrument.Clarinet(), clef.TrebleClef()),
    ('viola', 'Viola', 'Va.', instrument.Viola(), clef.AltoClef()),
    ('cello', 'Violoncello', 'Vc.', instrument.Violoncello(), clef.BassClef()),
    ('piano_r', 'Piano, upper staff', 'Pno.', instrument.Piano(), clef.TrebleClef()),
    ('piano_l', 'Piano, lower staff', 'Pno.', instrument.Piano(), clef.BassClef())
]
for pid, name, abbreviation, inst, staff_clef in settings:
    p = stream.PartStaff(id=pid) if pid.startswith('piano') else stream.Part(id=pid)
    p.partName = name
    p.partAbbreviation = abbreviation
    p.atSoundingPitch = True
    p.insert(0, inst)
    parts[pid] = p
    score.insert(0, p)

score.insert(0, layout.StaffGroup(
    [parts['piano_r'], parts['piano_l']], name='Piano',
    abbreviation='Pno.', symbol='brace', barTogether=True))

registers = {'flute': (72, 91), 'clarinet': (55, 79),
             'viola': (48, 72), 'cello': (36, 60)}

def modal_pitch(h, degree, voice):
    bass, voicing, root, intervals = harmonies[h]
    octaves, step = divmod(degree, 7)
    value = 60 + root + intervals[step] + 12 * octaves
    if voice == 'flute':
        value += 12
    elif voice == 'viola':
        value -= 12
    elif voice == 'cello':
        value -= 24
    lo, hi = registers[voice]
    while value > hi:
        value -= 12
    while value < lo:
        value += 12
    return value

motif = [0, 1, 4, 3, 2, 1]

def motif_events(h, voice, length, degrees=None):
    ds = motif if degrees is None else degrees
    rhythm = {5: [0.5, 0.5, 1, 1.5, 0.5, 1],
              4: [0.5, 0.5, 1, 1, 0.5, 0.5],
              3.5: [0.5, 0.5, 1, 0.5, 0.5, 0.5]}[float(length)]
    return [(modal_pitch(h, d, voice), q) for d, q in zip(ds, rhythm)]

def add_events(measure, events, legato=False, short=False, accents=()):
    assert abs(sum(float(q) for _, q in events) - float(measure.barDuration.quarterLength)) < 0.00001
    groups = []
    current = []
    for index, (value, q) in enumerate(events):
        if value is None:
            obj = note.Rest(quarterLength=q)
            if current:
                groups.append(current)
                current = []
        elif isinstance(value, (list, tuple)):
            obj = chord.Chord(value, quarterLength=q)
            current.append(obj)
        else:
            obj = note.Note(value, quarterLength=q)
            current.append(obj)
        if not obj.isRest:
            if short:
                obj.articulations.append(articulations.Staccato())
            if index in accents:
                obj.articulations.append(articulations.Accent())
        measure.append(obj)
    if current:
        groups.append(current)
    if legato:
        for group in groups:
            if len(group) >= 2:
                measure.insert(0, spanner.Slur(group[0], group[-1]))

section_labels = {0: 'I. Listening — spacious, not mechanical',
                  8: 'II. Questions, in 2 + 2 + 3',
                  16: 'III. Many paths, one pulse',
                  24: 'IV. Let the low voice speak',
                  32: 'V. Memory, with room around it'}
tempo_changes = {0: 66, 8: 78, 16: 88, 24: 64, 32: 58, 38: 50}
dynamic_levels = {
    'flute': ['p', 'mp', 'mf', 'pp', 'p'],
    'clarinet': ['pp', 'mp', 'mf', 'p', 'pp'],
    'viola': ['pp', 'p', 'mf', 'pp', 'pp'],
    'cello': ['p', 'mp', 'mf', 'mp', 'pp'],
    'piano_r': ['pp', 'p', 'mf', 'pp', 'pp'],
    'piano_l': ['pp', 'p', 'mp', 'pp', 'pp']
}

for i, h in enumerate(progression):
    section = i // 8
    local = i % 8
    L = float(lengths[i])
    bass, voicing, root, intervals = harmonies[h]
    fifth = bass + (6 if h == 'E' else 7)
    ev = {}

    if section == 0:
        ev['flute'] = [(None, L)] if local < 2 else motif_events(h, 'flute', L)
        if local in (3, 7):
            ev['flute'][-1] = (None, ev['flute'][-1][1])
        ev['clarinet'] = [(None, L)] if local < 4 else (
            [(None, 1)] + [(modal_pitch(h, d, 'clarinet'), q)
            for d, q in zip([4, 3, 2, 1, 0], [0.5, 0.5, 0.5, 0.5, L - 3])])
        ev['viola'] = [(None, 1), (modal_pitch(h, 2, 'viola'), (L - 1) / 2),
                       (modal_pitch(h, 6, 'viola'), (L - 1) / 2)]
        ev['cello'] = [(bass, L - 1), (fifth, 1)]
    elif section == 1:
        if local % 2 == 0:
            ev['flute'] = motif_events(h, 'flute', L)
            ev['clarinet'] = [(modal_pitch(h, 2, 'clarinet'), 2), (None, 1.5)]
        else:
            ev['flute'] = [(None, 1), (modal_pitch(h, 6, 'flute'), 2.5)]
            ev['clarinet'] = motif_events(h, 'clarinet', L, [4, 3, 0, 1, 2, 3])
        ev['viola'] = [(None, 0.5), (modal_pitch(h, 2, 'viola'), 0.5),
                       (modal_pitch(h, 4, 'viola'), 0.5), (None, 0.5),
                       (modal_pitch(h, 6, 'viola'), 1), (modal_pitch(h, 5, 'viola'), 0.5)]
        ev['cello'] = [(bass, 1), (fifth, 1), (bass, 1.5)]
    elif section == 2:
        shift = [0, 1, 2, 1, 0, 2, 1, 0][local]
        ev['flute'] = motif_events(h, 'flute', L, [d + shift for d in motif])
        ev['clarinet'] = [(None, 0.5)] + [
            (modal_pitch(h, d, 'clarinet'), q)
            for d, q in zip([4, 2, 3, 1, 0], [0.5, 0.5, 1, 1, L - 3.5])]
        ev['viola'] = [(None, 0.5), (modal_pitch(h, 2, 'viola'), 0.5),
                       (modal_pitch(h, 4, 'viola'), 1),
                       (modal_pitch(h, 6, 'viola'), 1),
                       (modal_pitch(h, 5, 'viola'), L - 3)]
        ev['cello'] = [(bass, 1), (fifth, 1), (modal_pitch(h, 6, 'cello'), L - 2)]
    elif section == 3:
        degrees, rhythm = ([0, 1, 4], [1, 1, 2]) if local % 2 == 0 else ([3, 2, 1], [2, 1, 1])
        ev['cello'] = [(modal_pitch(h, d, 'cello'), q) for d, q in zip(degrees, rhythm)]
        ev['flute'] = [(None, L)] if local % 2 == 0 else [
            (None, 1), (modal_pitch(h, 4, 'flute'), 2), (modal_pitch(h, 1, 'flute'), 1)]
        ev['clarinet'] = [(modal_pitch(h, 2, 'clarinet'), 3), (None, 1)]
        ev['viola'] = [(modal_pitch(h, 2, 'viola'), L)]
    else:
        if local < 4:
            ev['flute'] = motif_events(h, 'flute', L)
            ev['flute'][-1] = (None, ev['flute'][-1][1])
        else:
            ev['flute'] = [(None, 1), (modal_pitch(h, 4, 'flute'), 2),
                           (modal_pitch(h, 1, 'flute'), 1)]
        ev['clarinet'] = [(None, 1), (modal_pitch(h, 2, 'clarinet'), L - 2), (None, 1)]
        ev['viola'] = [(modal_pitch(h, 6, 'viola'), L)] if local % 2 == 0 else [(None, L)]
        ev['cello'] = [(bass, L)]

    if section == 3:
        ev['piano_r'] = [(None, 0.5), (voicing, 1.5), (None, 0.5), (voicing[1:], 1.5)]
        ev['piano_l'] = [(bass, L)]
    else:
        pattern = [0, 2, 1, 3] if section != 1 else [0, 2, 1, 2, 3, 1, 2]
        ev['piano_r'] = []
        for k in range(int(L * 2)):
            value = voicing[pattern[k % len(pattern)] % len(voicing)]
            if section == 0 and k in (3, 7):
                value = None
            elif section == 4 and k % 2 == 1:
                value = None
            elif section == 2 and k % 4 == 0:
                value = [value, value + 12]
            ev['piano_r'].append((value, 0.5))
        if section == 1:
            ev['piano_l'] = [(bass, 1), (fifth, 1), (bass, 1.5)]
        elif section == 2:
            ev['piano_l'] = [([bass, fifth], 1), (bass + 12, 1), ([bass, fifth], L - 2)]
        else:
            ev['piano_l'] = [([bass, fifth], L - 1), (None, 1)]

    # A common arrival, followed by a full beat of shared silence.
    if i == 38:
        ev = {'flute': [(76, 2), (74, 2)],
              'clarinet': [(69, 3), (None, 1)],
              'viola': [(53, 4)], 'cello': [(38, 4)],
              'piano_r': [([57, 62, 64, 65], 4)],
              'piano_l': [([38, 45], 4)]}
    elif i == 39:
        final_values = {'flute': 74, 'clarinet': 64, 'viola': 57, 'cello': 38,
                        'piano_r': [50, 57, 64, 65], 'piano_l': [38, 45]}
        ev = {pid: [(value, 3), (None, 1)] for pid, value in final_values.items()}

    for pid, name, abbreviation, inst, staff_clef in settings:
        m = stream.Measure(number=i + 1)
        # Explicit internal meter also makes event-duration validation unambiguous.
        m.insert(0, meter.TimeSignature(meters[i]))
        if i == 0:
            m.insert(0, staff_clef)
        if local == 0:
            m.insert(0, dynamics.Dynamic(dynamic_levels[pid][section]))
        if pid == 'flute':
            if i in tempo_changes:
                m.insert(0, tempo.MetronomeMark(number=tempo_changes[i], referent=note.Note(quarterLength=1)))
            if i in section_labels:
                m.insert(0, expressions.TextExpression(section_labels[i]))
        if pid == 'piano_r' and i == 0:
            m.insert(0, expressions.TextExpression('lightly; pedal changes with each harmony'))
        if pid == 'cello' and i in (8, 16, 24):
            m.insert(0, expressions.TextExpression({8: 'pizz.', 16: 'arco', 24: 'cantabile'}[i]))
        short = section == 1 and pid in ('viola', 'cello')
        accents = (0, 2, 4) if section == 1 and pid == 'piano_r' else ()
        add_events(m, ev[pid], legato=pid in ('flute', 'clarinet', 'cello') and not short,
                   short=short, accents=accents)
        if i == 39:
            m.rightBarline = bar.Barline('final')
        parts[pid].append(m)

# Phrase-scale dynamics, rather than a separate swell on every small cell.
for pid, p in parts.items():
    for first_bar, last_bar, wedge_class in [
        (13, 17, dynamics.Crescendo),
        (21, 25, dynamics.Diminuendo),
        (33, 39, dynamics.Diminuendo)
    ]:
        first_notes = list(p.measure(first_bar).recurse().notes)
        last_notes = list(p.measure(last_bar).recurse().notes)
        if first_notes and last_notes:
            p.insert(0, wedge_class(first_notes[0], last_notes[-1]))

# The cello's enlarged motive connects each two-bar phrase in the fourth panel.
for first_bar in (25, 27, 29, 31):
    start = list(parts['cello'].measure(first_bar).recurse().notes)[0]
    finish = list(parts['cello'].measure(first_bar + 1).recurse().notes)[-1]
    parts['cello'].insert(0, spanner.Slur(start, finish))

assert all(abs(float(p.highestTime) - 168.0) < 0.00001 for p in parts.values())
